const { build } = require('esbuild');
const scr = process.argv[2];
async function bundle(entry, out) {
  await build({ entryPoints: [entry], bundle: true, format: 'esm', platform: 'node', write: true, outfile: out, absWorkingDir: root, logLevel: 'silent' });
  return import(out + '?v=' + Date.now());
}
const A = await bundle(root + '/src/module.ts', scr + '/orig.mjs');
const B = await bundle(root + '/out/module.ts', scr + '/new.mjs');

const names = ['Ann','bob','cy','dana','eli'];
const rnd = n => Math.floor(Math.random() * n);
const row = () => ({ id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43) });
const chars = '0123456789.+- exX'.split('').concat(['e','x']);
const strFrom = () => { const L = rnd(9); let s=''; for (let i=0;i<L;i++) s += chars[rnd(chars.length)]; return s; };
const fixed = ['', ' ', '92858+99', '.72e', '0x1A', '-0x1A', '+0x1f', '1e5', '1e-3', '.', '+', '-', 'e', 'x', '0x', '1 2', ' 12 ', '1.', '.5', '5e+', '00012', '0.0', '-0', '+5', '9e9', '1x', 'xe'];

let fails = 0, n = 0;
const eq = (a, b) => Object.is(a, b) || (a !== a && b !== b);
const cmpObj = (a, b) => JSON.stringify(a) === JSON.stringify(b) && Object.keys(a).join() === Object.keys(b).join();

for (let i = 0; i < 20000; i++) {
  const r = row(); n++;
  if (!cmpObj(A.publicFields(r), B.publicFields(r))) { fails++; if (fails < 5) console.log('publicFields', r); }
  const len = rnd(13); const rows = Array.from({ length: len }, row); n++;
  if (!eq(A.totalAge(rows), B.totalAge(rows))) { fails++; if (fails < 5) console.log('totalAge', rows); }
  const s = i < fixed.length ? fixed[i] : strFrom(); n++;
  if (!eq(A.parseAmount(s), B.parseAmount(s))) { fails++; if (fails < 5) console.log('parseAmount', JSON.stringify(s), A.parseAmount(s), B.parseAmount(s)); }
}
for (const s of fixed) { n++; if (!eq(A.parseAmount(s), B.parseAmount(s))) { fails++; console.log('fixed', JSON.stringify(s)); } }
const ex = [[{"id":1,"name":"jung","age":24}]];
console.log('publicFields examples', cmpObj(A.publicFields({"id":1,"name":"jung","age":24}), B.publicFields({"id":1,"name":"jung","age":24})));
console.log('totalAge examples', A.totalAge([{id:9,name:'kim',age:45},{id:6,name:'park',age:30},{id:9,name:'lee',age:49}]), B.totalAge([{id:9,name:'kim',age:45},{id:6,name:'park',age:30},{id:9,name:'lee',age:49}]));
console.log('parseAmount examples', A.parseAmount("92858+99"), B.parseAmount("92858+99"), A.parseAmount(".72e"), B.parseAmount(".72e"));
console.log(`checked ${n} comparisons, mismatches: ${fails}`);
EOF
node "$SCR/equiv.mjs" "$SCR" 2>&1 | tail -20

